select '0f1ef133-918b-566c-9a4a-024952ef78e8 public mapping' check_name,((select count(*) from jsonb_array_elements(math_private.release_catalog('6e289e0f-e5b9-5f47-8de6-4d9fb58cdb3f')) x where x->>'leaf_id'='de5473e3-fc93-5d6b-b831-5b2fa8839bdc' and x->>'essay_question_id'='0f1ef133-918b-566c-9a4a-024952ef78e8')=1) passed
union all
select '0f1ef133-918b-566c-9a4a-024952ef78e8 profile' check_name,((with candidates as(select ep.id,case ep.scope when 'LEAF' then 4 when 'PROBLEM' then 3 when 'EXAM' then 2 else 1 end rank from public.math_subproblems l join public.math_problems pr on pr.id=l.problem_id join public.math_problem_sets ps on ps.id=pr.problem_set_id join public.math_evaluation_profiles ep on ep.state='ACTIVE' and ep.response_format=l.response_format and (ep.leaf_id=l.id or ep.problem_id=l.problem_id or ep.essay_exam_id=ps.essay_exam_id or (ep.scope='COMMON_MATH_RUBRIC' and l.allow_common_rubric)) where l.id='de5473e3-fc93-5d6b-b831-5b2fa8839bdc' and pr.state='ACTIVE' and ps.state='ACTIVE') select count(*)=1 and bool_and(id='0a47f8a6-8d29-529b-b8ab-b523cb216f00'::uuid) from candidates where rank=(select max(rank) from candidates))) passed
union all
select '0f1ef133-918b-566c-9a4a-024952ef78e8 Worker evidence' check_name,(exists(select 1 from public.math_subproblems l join public.math_problems pr on pr.id=l.problem_id where l.id='de5473e3-fc93-5d6b-b831-5b2fa8839bdc' and jsonb_array_length(math_private.hanyang_worker_references(jsonb_build_object('leaf',to_jsonb(l),'problem',to_jsonb(pr),'sources',(select jsonb_agg(to_jsonb(s)) from public.math_source_artifacts s where s.problem_id=pr.id)))->'official_images')>0)) passed
